send(msg);

const assetPath = AssetPath.path || "-";
const categoryPath = `${assetPath}.Job Activity Category`;
const alarmPath = `${assetPath}.Job Activity Alarm`;
const workOrder = String(asset.get(`${assetPath}.Work Order`, "") ?? "").trim();

let activeCategory = "-";
const activeCategories = [];

if (workOrder && workOrder !== "-") {
  const basePath = `${assetPath}/Job/${workOrder}/Activity`;
  const [setupOpen, idleOpen, prodOpen] = await Promise.all([
    eventSys.get(`${basePath}/Setup/*`, "*", "*", "open", {}, { limit: 200 }),
    eventSys.get(`${basePath}/Idle/*`, "*", "*", "open", {}, { limit: 200 }),
    eventSys.get(`${basePath}/Production/*`, "*", "*", "open", {}, { limit: 200 })
  ]);

  if (setupOpen.length > 0) activeCategories.push("Setup");
  if (idleOpen.length > 0) activeCategories.push("Idle");
  if (prodOpen.length > 0) activeCategories.push("Production");
}

if (activeCategories.length === 1) {
  activeCategory = activeCategories[0];
  await asset.set(categoryPath, activeCategory);
  await asset.set(alarmPath, "-");
} else if (activeCategories.length === 0) {
  await asset.set(categoryPath, "-");
  await asset.set(alarmPath, "-");
} else {
  await asset.set(categoryPath, "-");
  await asset.set(alarmPath, `!!!Multiple activity categories active: ${activeCategories.join(", ")}!!!`);
}

msg.activityCategory = activeCategory;
msg.activeCategories = activeCategories;

send(msg);

const assetPath = AssetPath.path || "-";
const rawPath = `${assetPath}.Encoder Input Raw Value`;
const prevRawPath = `${assetPath}.Encoder Input Prev Value`;
const machineSpeedPath = `${assetPath}.Machine Speed`;
const setupPath = `${assetPath}.Paper Consumed Setup`;
const idlePath = `${assetPath}.Paper Consumed Idle`;
const prodPath = `${assetPath}.Paper Consumed Production`;
const wastePath = `${assetPath}.Total Paper Waste`;
const totalConsumedPath = `${assetPath}.Total Paper Consumed`;
const categoryPath = `${assetPath}.Job Activity Category`;

const raw = Number(asset.get(rawPath, 0) ?? 0);
const prevRaw = Number(asset.get(prevRawPath, 0) ?? 0);
const activeCategory = String(msg.activityCategory ?? asset.get(categoryPath, "-") ?? "-").trim();

const delta = raw >= prevRaw ? (raw - prevRaw) : raw;
if (!Number.isFinite(delta) || delta < 0) {
  await asset.set(prevRawPath, raw);
  send(msg);
  return;
}

await asset.set(machineSpeedPath, delta * 0.6);

if (delta === 0 || !["Setup", "Idle", "Production"].includes(activeCategory)) {
  await asset.set(prevRawPath, raw);
  send(msg);
  return;
}

const setupPrev = Number(asset.get(setupPath, 0) ?? 0);
const idlePrev = Number(asset.get(idlePath, 0) ?? 0);
const prodPrev = Number(asset.get(prodPath, 0) ?? 0);

let setupNew = setupPrev;
let idleNew = idlePrev;
let prodNew = prodPrev;

if (activeCategory === "Setup") setupNew += delta / 100;
else if (activeCategory === "Idle") idleNew += delta / 100;
else if (activeCategory === "Production") prodNew += delta / 100;

const waste = setupNew + idleNew;
const totalConsumed = waste + prodNew;

await asset.setMany([
  { path: setupPath, value: setupNew },
  { path: idlePath, value: idleNew },
  { path: prodPath, value: prodNew },
  { path: wastePath, value: waste },
  { path: totalConsumedPath, value: totalConsumed },
  { path: prevRawPath, value: raw }
]);

